import { z } from 'zod';

/**
 * Fonts the owner can choose for the website and the House.
 *
 * Every font here is self-hosted by both Next.js apps (next/font), so choosing one
 * never sends visitors to Google and works offline in the House. Each app declares
 * exactly these keys in lib/fonts.ts, generated by scripts/gen-fonts.mjs.
 */
export const FONT_CATALOG = [
  // Serif — headings with character
  { key: 'fraunces', family: 'Fraunces', kind: 'serif', note: 'Soft, warm editorial serif — the Reberon original' },
  { key: 'playfair-display', family: 'Playfair Display', kind: 'serif', note: 'High-contrast, classic luxury' },
  { key: 'cormorant-garamond', family: 'Cormorant Garamond', kind: 'serif', note: 'Light, elegant, very refined' },
  { key: 'bodoni-moda', family: 'Bodoni Moda', kind: 'serif', note: 'Fashion-magazine contrast' },
  { key: 'lora', family: 'Lora', kind: 'serif', note: 'Friendly, calligraphic, easy to read' },
  { key: 'eb-garamond', family: 'EB Garamond', kind: 'serif', note: 'Old-style book serif' },
  { key: 'libre-baskerville', family: 'Libre Baskerville', kind: 'serif', note: 'Sturdy and traditional' },
  { key: 'source-serif-4', family: 'Source Serif 4', kind: 'serif', note: 'Modern, crisp reading serif' },
  { key: 'newsreader', family: 'Newsreader', kind: 'serif', note: 'Newspaper calm, works for long text' },
  { key: 'instrument-serif', family: 'Instrument Serif', kind: 'serif', note: 'Condensed display serif (one weight)', fixedWeight: 400 },
  { key: 'dm-serif-display', family: 'DM Serif Display', kind: 'serif', note: 'Bold display serif (one weight)', fixedWeight: 400 },
  // Sans — clean text and modern headings
  { key: 'inter', family: 'Inter', kind: 'sans', note: 'Neutral and very legible — the Reberon original' },
  { key: 'plus-jakarta-sans', family: 'Plus Jakarta Sans', kind: 'sans', note: 'Friendly geometric — the House original' },
  { key: 'manrope', family: 'Manrope', kind: 'sans', note: 'Modern, open, slightly technical' },
  { key: 'dm-sans', family: 'DM Sans', kind: 'sans', note: 'Low-contrast geometric' },
  { key: 'outfit', family: 'Outfit', kind: 'sans', note: 'Round geometric, contemporary' },
  { key: 'figtree', family: 'Figtree', kind: 'sans', note: 'Clean and friendly' },
  { key: 'work-sans', family: 'Work Sans', kind: 'sans', note: 'Grotesque, good on screens' },
  { key: 'nunito-sans', family: 'Nunito Sans', kind: 'sans', note: 'Soft and warm' },
  { key: 'montserrat', family: 'Montserrat', kind: 'sans', note: 'Wide geometric, strong headings' },
  { key: 'raleway', family: 'Raleway', kind: 'sans', note: 'Elegant thin-to-bold sans' },
  { key: 'source-sans-3', family: 'Source Sans 3', kind: 'sans', note: 'Humanist, comfortable for reading' },
  { key: 'urbanist', family: 'Urbanist', kind: 'sans', note: 'Geometric with a modern feel' },
  { key: 'space-grotesk', family: 'Space Grotesk', kind: 'sans', note: 'Quirky, technical grotesque' },
  { key: 'sora', family: 'Sora', kind: 'sans', note: 'Wide and confident' },
  { key: 'libre-franklin', family: 'Libre Franklin', kind: 'sans', note: 'Classic American gothic' },
] as const;

export type FontKey = (typeof FONT_CATALOG)[number]['key'];
export const FONT_KEYS = FONT_CATALOG.map((f) => f.key) as [FontKey, ...FontKey[]];
export const FONT_BY_KEY = Object.fromEntries(FONT_CATALOG.map((f) => [f.key, f])) as Record<FontKey, (typeof FONT_CATALOG)[number]>;

const zFont = z.enum(FONT_KEYS);
const zTracking = z.enum(['tight', 'normal', 'wide']);

export const zWebsiteTypography = z.object({
  heading: zFont.catch('fraunces'),
  body: zFont.catch('inter'),
  /** 300–800; ignored by one-weight fonts. */
  headingWeight: z.number().int().min(200).max(900).catch(380),
  headingTracking: zTracking.catch('tight'),
  headingItalic: z.boolean().catch(false),
  /** Whole-site text size: 0.9 (smaller) … 1.15 (larger). */
  scale: z.number().min(0.85).max(1.2).catch(1),
});

export const zHouseTypography = z.object({
  heading: zFont.catch('plus-jakarta-sans'),
  body: zFont.catch('inter'),
  headingWeight: z.number().int().min(200).max(900).catch(600),
  scale: z.number().min(0.85).max(1.2).catch(1),
});

export const zTypography = z.object({
  website: zWebsiteTypography.catch(() => zWebsiteTypography.parse({})),
  house: zHouseTypography.catch(() => zHouseTypography.parse({})),
});

export type WebsiteTypography = z.infer<typeof zWebsiteTypography>;
export type HouseTypography = z.infer<typeof zHouseTypography>;
export type Typography = z.infer<typeof zTypography>;

export const DEFAULT_TYPOGRAPHY: Typography = zTypography.parse({});

/** Any stored value (missing, partial or old) becomes a complete, valid typography. */
export function readTypography(value: unknown): Typography {
  const r = zTypography.safeParse(value ?? {});
  return r.success ? r.data : DEFAULT_TYPOGRAPHY;
}

const SERIF_FALLBACK = "'Iowan Old Style', Georgia, serif";
const SANS_FALLBACK = "ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif";
const stack = (k: FontKey) => `var(--ff-${k}), ${FONT_BY_KEY[k].kind === 'serif' ? SERIF_FALLBACK : SANS_FALLBACK}`;
const TRACKING = { tight: '-0.015em', normal: '0em', wide: '0.02em' } as const;

/** CSS custom properties that apply a typography to a page (set on <html>). */
export function typographyVars(t: Typography, app: 'website' | 'house'): Record<string, string> {
  if (app === 'website') {
    const w = t.website;
    const fixed = 'fixedWeight' in FONT_BY_KEY[w.heading] ? (FONT_BY_KEY[w.heading] as { fixedWeight: number }).fixedWeight : null;
    return {
      '--font-display': stack(w.heading),
      '--font-sans': stack(w.body),
      '--heading-weight': String(fixed ?? w.headingWeight),
      '--heading-tracking': TRACKING[w.headingTracking],
      '--heading-style': w.headingItalic ? 'italic' : 'normal',
      '--text-scale': String(w.scale),
    };
  }
  const h = t.house;
  const fixed = 'fixedWeight' in FONT_BY_KEY[h.heading] ? (FONT_BY_KEY[h.heading] as { fixedWeight: number }).fixedWeight : null;
  return {
    '--font-display': stack(h.heading),
    '--font-sans': stack(h.body),
    '--heading-weight': String(fixed ?? h.headingWeight),
    '--text-scale': String(h.scale),
  };
}
